    <link rel="stylesheet" href="styles.css">
</head>
<body>
    <div id="root"></div>

    <script>
        // React-style component structure
        function NotificationPreferencesForm() {
            return `
                <div class="form-container">
                    <form id="preferencesForm" class="form">
                        <h1 class="form-title">Notification Preferences</h1>

                        <div class="form-field">
                            <fieldset class="radio-group-fieldset">
                                <legend class="radio-group-legend">How do you prefer to receive notifications?</legend>

                                <div class="radio-option">
                                    <input 
                                        type="radio" 
                                        id="email" 
                                        name="notification" 
                                        value="Email"
                                        required
                                    >
                                    <label for="email" class="radio-label">Email</label>
                                </div>

                                <div class="radio-option">
                                    <input 
                                        type="radio" 
                                        id="sms" 
                                        name="notification" 
                                        value="SMS"
                                    >
                                    <label for="sms" class="radio-label">SMS</label>
                                </div>

                                <div class="radio-option">
                                    <input 
                                        type="radio" 
                                        id="push" 
                                        name="notification" 
                                        value="Push Notifications"
                                    >
                                    <label for="push" class="radio-label">Push Notifications</label>
                                </div>
                            </fieldset>
                        </div>

                        <button type="submit" class="submit-button">Save Preferences</button>
                    </form>
                </div>
            `;
        }

        // Render the component
        function render() {
            const root = document.getElementById('root');
            root.innerHTML = NotificationPreferencesForm();
            attachEventListeners();
        }

        // Attach event listeners
